#include <iostream>
#include <cmath>
#include <iomanip>

class Point {
private:
    double x;
    double y;

public:
    void setCoordinates(double xVal, double yVal) {
        x = xVal;
        y = yVal;
    }

    double distanceTo(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return std::sqrt(dx * dx + dy * dy);
    }

    // Using (*this) to compute triangle perimeter formed by *this, p2, and p3
    double trianglePerimeter(const Point& p2, const Point& p3) const {
        double edge1 = (*this).distanceTo(p2);
        double edge2 = p2.distanceTo(p3);
        double edge3 = p3.distanceTo(*this);
        return edge1 + edge2 + edge3;
    }
};

int main() {
    Point p1, p2, p3;
    p1.setCoordinates(0.0, 0.0);
    p2.setCoordinates(3.0, 0.0);
    p3.setCoordinates(0.0, 4.0);

    double perimeter = p1.trianglePerimeter(p2, p3);
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Perimeter = " << perimeter << std::endl;

    return 0;
}

#include <iostream>

class GraphicPoint {
private:
    int x;
    int y;
    int color;

public:
    // Default constructor defined inline inside class
    GraphicPoint() : x(0), y(0), color(1) {
        std::cout << "Default constructor called" << std::endl;
    }

    // Parameterized constructor with default argument colorVal = 15
    // Prototype declared inside class
    GraphicPoint(int xVal, int yVal, int colorVal = 15);

    void display() const {
        std::cout << "Point(" << x << ", " << y << ") - Color: " << color << std::endl;
    }
};

// Constructor defined outside class definition
GraphicPoint::GraphicPoint(int xVal, int yVal, int colorVal) 
    : x(xVal), y(yVal), color(colorVal) {
    std::cout << "Parameterized constructor called" << std::endl;
}

int main() {
    // Invoking default constructor
    GraphicPoint p1;
    p1.display();

    // Invoking parameterized constructor using default color argument (15)
    GraphicPoint p2(10, 20);
    p2.display();

    // Invoking parameterized constructor with all arguments explicitly provided
    GraphicPoint p3(30, 40, 4);
    p3.display();

    return 0;
}
